INSERT INTO repo_esd_objectives (esd_objective_id, domain, objective_no, text, status) VALUES ('ESD_SDG11_COG_01', 'Cognitive', '1', 'The learner understands basic physical, social and psychological human needs and is able to identify how these needs are currently addressed in their own physical urban, peri-urban and rural settlements.', 'Active'), ('ESD_SDG11_COG_02', 'Cognitive', '2', 'The learner is able to evaluate and compare the sustainability of their and other settlements’ systems in meeting their needs particularly in the areas of food, energy, transport, water, safety, waste treatment, inclusion and accessibility, education, integration of green spaces and disaster risk reduction.', 'Active'), ('ESD_SDG11_COG_03', 'Cognitive', '3', 'The learner understands the historical reasons for settlement patterns and while respecting cultural heritage, understands the need to find compromises to develop improved sustainable systems.', 'Active'), ('ESD_SDG11_COG_04', 'Cognitive', '4', 'The learner knows the basic principles of sustainable planning and building, and can identify opportunities for making their own area more sustainable and inclusive.', 'Active'), ('ESD_SDG11_COG_05', 'Cognitive', '5', 'The learner understands the role of local decision-makers and participatory governance and the importance of representing a sustainable voice in planning and policy for their area.', 'Active'), ('ESD_SDG11_SOC_01', 'Socio-emotional', '1', 'The learner is able to use their voice, to identify and use entry points for the public in the local planning systems, to call for the investment in sustainable infrastructure, buildings and parks in their area and to debate the merits of long-term planning.', 'Active'), ('ESD_SDG11_SOC_02', 'Socio-emotional', '2', 'The learner is able to connect with and help community groups locally and online in developing a sustainable future vision of their community.', 'Active'), ('ESD_SDG11_SOC_03', 'Socio-emotional', '3', 'The learner is able to reflect on their region in the development of their own identity, understanding the roles that the natural, social and technical environments have had in building their identity and culture.', 'Active'), ('ESD_SDG11_SOC_04', 'Socio-emotional', '4', 'The learner is able to contextualize their needs within the needs of the greater surrounding ecosystems, both locally and globally, for more sustainable human settlements.', 'Active'), ('ESD_SDG11_SOC_05', 'Socio-emotional', '5', 'The learner is able to feel responsible for the environmental and social impacts of their own individual lifestyle.', 'Active'), ('ESD_SDG11_BEH_01', 'Behavioural', '1', 'The learner is able to plan, implement and evaluate community-based sustainability projects.', 'Active'), ('ESD_SDG11_BEH_02', 'Behavioural', '2', 'The learner is able to participate in and influence decision processes about their community.', 'Active'), ('ESD_SDG11_BEH_03', 'Behavioural', '3', 'The learner is able to speak against/for and to organize their voice against/for decisions made for their community.', 'Active'), ('ESD_SDG11_BEH_04', 'Behavioural', '4', 'The learner is able to co-create an inclusive, safe, resilient and sustainable community.', 'Active'), ('ESD_SDG11_BEH_05', 'Behavioural', '5', 'The learner is able to promote low carbon approaches at the local level.', 'Active'), ('ESD_SDG12_COG_01', 'Cognitive', '1', 'The learner understands how individual lifestyle choices influence social, economic and environmental development.', 'Active'), ('ESD_SDG12_COG_02', 'Cognitive', '2', 'The learner understands production and consumption patterns and value chains and the interrelatedness of production and consumption (supply and demand, toxics, CO2 emissions, waste generation, health, working conditions, poverty, etc. ).', 'Active'), ('ESD_SDG12_COG_03', 'Cognitive', '3', 'The learner knows roles, rights and duties of different actors in production and consumption (media and advertising, enterprises, municipalities, legislation, consumers, etc. ).', 'Active'), ('ESD_SDG12_COG_04', 'Cognitive', '4', 'The learner knows about strategies and practices of sustainable production and consumption.', 'Active'), ('ESD_SDG12_COG_05', 'Cognitive', '5', 'The learner understands dilemmas/trade-offs related to and system changes necessary for achieving sustainable consumption and production.', 'Active'), ('ESD_SDG12_SOC_01', 'Socio-emotional', '1', 'The learner is able to communicate the need for sustainable practices in production and consumption.', 'Active'), ('ESD_SDG12_SOC_02', 'Socio-emotional', '2', 'The learner is able to encourage others to engage in sustainable practices in consumption and production.', 'Active'), ('ESD_SDG12_SOC_03', 'Socio-emotional', '3', 'The learner is able to differentiate between needs and wants and to reflect on their own individual consumer behaviour in light of the needs of the natural world, other people, cultures and countries, and future generations.', 'Active'), ('ESD_SDG12_SOC_04', 'Socio-emotional', '4', 'The learner is able to envision sustainable lifestyles.', 'Active'), ('ESD_SDG12_SOC_05', 'Socio-emotional', '5', 'The learner is able to feel responsible for the environmental and social impacts of their own individual behaviour as a producer or consumer.', 'Active'), ('ESD_SDG12_BEH_01', 'Behavioural', '1', 'The learner is able to plan, implement and evaluate consumption-related activities using existing sustainability criteria.', 'Active'), ('ESD_SDG12_BEH_02', 'Behavioural', '2', 'The learner is able to evaluate, participate in and influence decision-making processes about acquisitions in the public sector.', 'Active'), ('ESD_SDG12_BEH_03', 'Behavioural', '3', 'The learner is able to promote sustainable production patterns.', 'Active'), ('ESD_SDG12_BEH_04', 'Behavioural', '4', 'The learner is able take on critically on their role as an active stakeholder in the market.', 'Active'), ('ESD_SDG12_BEH_05', 'Behavioural', '5', 'The learner is able to challenge cultural and societal orientations in consumption and production.', 'Active'), ('ESD_SDG13_COG_01', 'Cognitive', '1', 'The learner understands the greenhouse effect as a natural phenomenon caused by an insulating layer of greenhouse gases.', 'Active'), ('ESD_SDG13_COG_02', 'Cognitive', '2', 'The learner understands the current climate change as an anthropogenic phenomenon resulting from increased greenhouse gas emissions.', 'Active'), ('ESD_SDG13_COG_03', 'Cognitive', '3', 'The learner knows which human activities – on a global, national, local and individual level – contribute most to climate change.', 'Active'), ('ESD_SDG13_COG_04', 'Cognitive', '4', 'The learner knows about the main ecological, social, cultural and economic consequences of climate change locally, nationally and globally and understands how these can themselves become catalysing, reinforcing factors for climate change.', 'Active'), ('ESD_SDG13_COG_05', 'Cognitive', '5', 'The learner knows about prevention, mitigation and adaptation strategies at different levels (global to individual) and for different contexts and their connections with disaster response and disaster risk reduction.', 'Active'), ('ESD_SDG13_SOC_01', 'Socio-emotional', '1', 'The learner is able to explain ecosystem dynamics and the environmental, social, economic and ethical impact of climate change.', 'Active'), ('ESD_SDG13_SOC_02', 'Socio-emotional', '2', 'The learner is able to encourage others to protect the climate.', 'Active'), ('ESD_SDG13_SOC_03', 'Socio-emotional', '3', 'The learner is able to collaborate with others and to develop commonly agreed-upon strategies to deal with climate change.', 'Active'), ('ESD_SDG13_SOC_04', 'Socio-emotional', '4', 'The learner is able to understand their personal impact on the world’s climate, from a local to a global perspective.', 'Active'), ('ESD_SDG13_SOC_05', 'Socio-emotional', '5', 'The learner is able to recognize that the protection of the global climate is an essential task for everyone and that we need to completely re-evaluate our worldview and everyday behaviours in light of this.', 'Active'), ('ESD_SDG13_BEH_01', 'Behavioural', '1', 'The learner is able to evaluate whether their private and job activities are climate friendly and – where not – to revise them.', 'Active'), ('ESD_SDG13_BEH_02', 'Behavioural', '2', 'The learner is able to act in favour of people threatened by climate change.', 'Active'), ('ESD_SDG13_BEH_03', 'Behavioural', '3', 'The learner is able to anticipate, estimate and assess the impact of personal, local and national decisions or activities on other people and world regions.', 'Active'), ('ESD_SDG13_BEH_04', 'Behavioural', '4', 'The learner is able to promote climate-protecting public policies.', 'Active'), ('ESD_SDG13_BEH_05', 'Behavioural', '5', 'The learner is able to support climate-friendly economic activities.', 'Active'), ('ESD_SDG14_COG_01', 'Cognitive', '1', 'The learner understands basic marine ecology, ecosystems, predator-prey relationships, etc.', 'Active'), ('ESD_SDG14_COG_02', 'Cognitive', '2', 'The learner understands the connection of many people to the sea and the life it holds, including the sea’s role as a provider of food, jobs and exciting opportunities.', 'Active'), ('ESD_SDG14_COG_03', 'Cognitive', '3', 'The learner knows the basic premise of climate change and the role of the oceans in moderating our climate.', 'Active'), ('ESD_SDG14_COG_04', 'Cognitive', '4', 'The learner understands threats to ocean systems such as pollution and overfishing and recognizes and can explain the relative fragility of many ocean ecosystems including coral reefs and hypoxic dead zones.', 'Active'), ('ESD_SDG14_COG_05', 'Cognitive', '5', 'The learner knows about opportunities for the sustainable use of living marine resources.', 'Active') ON CONFLICT DO NOTHING;